import messageLocalization from "../../../../common/core/localization/message";
import registerComponent from "../../../../core/component_registrator";
import $ from "../../../../core/renderer";
import eventsEngine from "../../../../events/core/events_engine";
import {
    addNamespace
} from "../../../../events/utils";
import {
    getPublicElement
} from "../../../core/m_element";
import {
    EmptyTemplate
} from "../../../core/templates/m_empty_template";
import {
    FunctionTemplate
} from "../../../core/templates/m_function_template";
import {
    dxClick
} from "../../../events/m_short";
import {
    APPOINTMENT_CLASSES,
    APPOINTMENT_TYPE_CLASSES,
    FOCUSED_STATE_CLASS
} from "../const";
import {
    DateFormatType,
    getDateTextFromTargetAppointment
} from "../utils/get_date_text";
import {
    EVENTS_NAMESPACE,
    ViewItem
} from "../view_item";
const DOUBLE_CLICK_EVENT_NAME = addNamespace("dxdblclick", EVENTS_NAMESPACE.namespace);
const CONTEXT_MENU_EVENT_NAME = addNamespace("dxcontextmenu", EVENTS_NAMESPACE.namespace);
export class BaseAppointmentView extends ViewItem {
    get targetedAppointmentData() {
        return this.option().targetedAppointmentData
    }
    get appointmentData() {
        return this.option().appointmentData
    }
    _setOptionsByReference() {
        super._setOptionsByReference();
        this._optionsByReference = Object.assign({}, this._optionsByReference, {
            appointmentData: true,
            targetedAppointmentData: true
        })
    }
    _init() {
        super._init();
        this.defaultAppointmentTemplate = new FunctionTemplate(options => {
            this.defaultAppointmentContent($(options.container))
        })
    }
    _initMarkup() {
        super._initMarkup();
        this.resize();
        this.applyElementClasses();
        this.applyAria();
        this.attachFocusEvents();
        this.attachClickEvent();
        this.attachDblClickEvent();
        this.attachContextMenuEvent();
        this.attachKeydownEvents();
        this.renderContentTemplate()
    }
    _dispose() {
        super._dispose();
        dxClick.off(this.$element(), EVENTS_NAMESPACE);
        eventsEngine.off(this.$element(), DOUBLE_CLICK_EVENT_NAME);
        eventsEngine.off(this.$element(), CONTEXT_MENU_EVENT_NAME)
    }
    applyElementClasses() {
        this.$element().addClass(APPOINTMENT_CLASSES.CONTAINER).toggleClass(APPOINTMENT_TYPE_CLASSES.RECURRING, this.isRecurring()).toggleClass(APPOINTMENT_TYPE_CLASSES.ALL_DAY, this.isAllDay())
    }
    applyAria() {
        this.$element().attr("role", "button").attr("tabindex", this.option().tabIndex)
    }
    attachClickEvent() {
        dxClick.off(this.$element(), EVENTS_NAMESPACE);
        dxClick.on(this.$element(), event => this.option().onClick(this, event), EVENTS_NAMESPACE)
    }
    attachDblClickEvent() {
        eventsEngine.off(this.$element(), DOUBLE_CLICK_EVENT_NAME);
        eventsEngine.on(this.$element(), DOUBLE_CLICK_EVENT_NAME, event => this.option().onDblClick(this, event))
    }
    attachContextMenuEvent() {
        eventsEngine.off(this.$element(), CONTEXT_MENU_EVENT_NAME);
        eventsEngine.on(this.$element(), CONTEXT_MENU_EVENT_NAME, event => this.option().onContextMenu(this, event))
    }
    onFocusIn() {
        this.$element().addClass(FOCUSED_STATE_CLASS);
        super.onFocusIn()
    }
    onFocusOut(e) {
        this.$element().removeClass(FOCUSED_STATE_CLASS);
        super.onFocusOut(e)
    }
    setTabIndex(tabIndex) {
        super.setTabIndex(tabIndex);
        this.$element().attr("tabindex", tabIndex ?? null)
    }
    getTitleText() {
        const dataAccessor = this.option().getDataAccessor();
        const titleText = dataAccessor.get("text", this.targetedAppointmentData);
        if (!titleText) {
            return messageLocalization.format("dxScheduler-noSubject")
        }
        return titleText
    }
    getDateText() {
        const dateText = getDateTextFromTargetAppointment(this.targetedAppointmentData, this.isAllDay() ? DateFormatType.DATE : DateFormatType.TIME);
        return dateText
    }
    isRecurring() {
        const dataAccessor = this.option().getDataAccessor();
        const recurrenceRule = dataAccessor.get("recurrenceRule", this.targetedAppointmentData);
        return Boolean(recurrenceRule)
    }
    isAllDay() {
        const dataAccessor = this.option().getDataAccessor();
        const allDay = dataAccessor.get("allDay", this.targetedAppointmentData);
        return Boolean(allDay)
    }
    renderContentTemplate() {
        const $content = $("<div>").addClass(APPOINTMENT_CLASSES.CONTENT).appendTo(this.$element());
        const template = this.option().appointmentTemplate instanceof EmptyTemplate ? this.defaultAppointmentTemplate : this.option().appointmentTemplate;
        template.render({
            container: getPublicElement($content),
            model: {
                appointmentData: this.appointmentData,
                targetedAppointmentData: this.targetedAppointmentData
            },
            index: this.option().index,
            onRendered: () => {
                this.option().onRendered({
                    appointmentElement: getPublicElement(this.$element()),
                    appointmentData: this.appointmentData,
                    targetedAppointmentData: this.targetedAppointmentData
                })
            }
        })
    }
    defaultAppointmentContent($container) {
        return $container
    }
}
registerComponent("dxSchedulerNewAppointment", BaseAppointmentView);
